package exercise
import("encoding/json";"errors";"strings")
type Options struct{Name string;TimeoutMS int;Enabled bool}
func Decode(raw []byte,strict bool)(Options,error){
 zero:=Options{};result:=Options{TimeoutMS:1000,Enabled:true}
 var fields map[string]json.RawMessage
 if err:=json.Unmarshal(raw,&fields);err!=nil{return zero,err}
 if fields==nil{return zero,errors.New("object required")}
 for key,value:=range fields{
  if key!="name"&&key!="timeout_ms"&&key!="enabled"{if strict{return zero,errors.New("unknown field")};continue}
  if string(value)=="null"{return zero,errors.New("null not permitted")}
  var err error
  switch key{case "name":err=json.Unmarshal(value,&result.Name);case "timeout_ms":err=json.Unmarshal(value,&result.TimeoutMS);case "enabled":err=json.Unmarshal(value,&result.Enabled)}
  if err!=nil{return zero,err}
 }
 if strings.TrimSpace(result.Name)==""||result.TimeoutMS<1||result.TimeoutMS>60000{return zero,errors.New("invalid name or timeout")}
 return result,nil
}
```

