package exercise
import("testing";"reflect";"bytes")
func TestCompatibilityPolicies(t *testing.T){
 samples:=[]struct{raw string;want Options}{
  {`{"name":"old-client"}`,Options{"old-client",1000,true}},
  {`{"name":"new-client","timeout_ms":4000,"enabled":false}`,Options{"new-client",4000,false}},
 }
 for _,sample:=range samples{for _,strict:=range []bool{false,true}{raw:=[]byte(sample.raw);before:=append([]byte(nil),raw...);got,err:=Decode(raw,strict);if err!=nil||!reflect.DeepEqual(got,sample.want)||!bytes.Equal(raw,before){t.Fatal("compatible sample",got,err)}}}
 raw:=[]byte(`{"name":"future","enabled":false,"future_field":{"nested":true}}`)
 got,err:=Decode(raw,false);if err!=nil||got!=(Options{"future",1000,false}){t.Fatal("protocol extension rejected",got,err)}
 if _,err=Decode(raw,true);err==nil{t.Fatal("configuration typo accepted")}
}
func TestPresenceNullAndInvalidValues(t *testing.T){
 for _,raw:=range []string{`{}`,`null`,`[]`,`{"name":null}`,`{"name":" "}`,`{"name":"x","timeout_ms":null}`,`{"name":"x","enabled":null}`,`{"name":"x","timeout_ms":0}`,`{"name":"x","timeout_ms":60001}`,`{"name":"x","timeout_ms":1.5}`,`{"name":"x","enabled":"false"}`,`{"name":"x"} {"name":"y"}`} {
  for _,strict:=range []bool{true,false}{if _,err:=Decode([]byte(raw),strict);err==nil{t.Fatal("invalid accepted",raw,strict)}}
 }
 if _,err:=Decode([]byte(`{"name":"x","timeuot_ms":5}`),true);err==nil{t.Fatal("misspelling accepted")}
}
